function Q({registerIndicator:C,sourceValues:V,nulls:I}){C({id:"oa-vama",name:"Volatility Adjusted Moving Average (VAMA)",category:"Trends IIR",placement:"onchart",inputs:[{key:"baseLength",type:"number",label:"Base Length",default:20,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"},{key:"shortAtr",type:"number",label:"Short ATR Period",default:10,min:1,max:5e3,step:1,tooltip:"Short-term ATR period used as the current volatility measurement."},{key:"longAtr",type:"number",label:"Long ATR Period",default:50,min:1,max:5e3,step:1,tooltip:"Long-term ATR period used as the reference volatility measurement."},{key:"minLength",type:"number",label:"Minimum Length",default:5,min:1,max:5e3,step:1},{key:"maxLength",type:"number",label:"Maximum Length",default:100,min:1,max:5e3,step:1}],plots:[{key:"vama",type:"line",title:"VAMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(i,a){const c=i.length,j=Math.max(1,Math.floor(Number(a.baseLength)||20)),b=Math.max(1,Math.floor(Number(a.shortAtr)||10)),d=Math.max(1,Math.floor(Number(a.longAtr)||50)),e=Math.max(1,Math.floor(Number(a.maxLength)||100)),k=Math.min(e,Math.max(1,Math.floor(Number(a.minLength)||5))),B=V(i,a.source??"close"),F=1e-10,E=1-1/b,O=1-1/d,s=new Array(c).fill(NaN),f=new Array(e).fill(NaN);let o=0,g=0,n=0,m=0,N=1,h=0,p=1,M=c>0?i[0].close:NaN;for(let t=0;t<c;t++){const l=i[t],W=l.high-l.low,q=Math.abs(l.high-M),z=Math.abs(l.low-M),y=Math.max(W,q,z);M=l.close;let u=NaN,L=NaN;Number.isFinite(y)&&(m=(m*(b-1)+y)/b,N*=E,u=N>F?m/(1-N):m,h=(h*(d-1)+y)/d,p*=O,L=p>F?h/(1-p):h);const D=Number.isFinite(u)&&Number.isFinite(L)&&u!==0?L/u:1,G=j*D,S=Math.max(k,Math.min(e,G)),H=Number.isFinite(S)?Math.trunc(S):k,w=f[o];Number.isFinite(w)&&(g-=w,n-=1);const r=B[t],x=Number.isFinite(r);x&&(g+=r,n+=1),f[o]=x?r:NaN,o=(o+1)%e;const R=n>0?g/n:r,J=Math.min(n,H);let P=0,A=0;for(let v=0;v<J;v++){const K=((o-1-v)%e+e)%e,T=f[K];Number.isFinite(T)&&(P+=T,A+=1)}A>0?s[t]=P/A:Number.isFinite(R)?s[t]=R:x&&(s[t]=r)}return{vama:I(s)}}})}export{Q as default};
